import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { MessageService } from 'primeng/api';
import { AdminContentService } from '../../../../../../libs/openapi/src/api/admin-content.service';
import { CreateContentRequestModel } from '../../../../../../libs/openapi/src/model/create-content-request-model';
import { UpdateContentRequestModel } from '../../../../../../libs/openapi/src/model/update-content-request-model';
import { contentTypeOptions } from '../../../../shared/constants/content-types.constants';

@Component({
  selector: 'app-content-form',
  templateUrl: './content-form.component.html',
  styleUrls: ['./content-form.component.scss'],
  providers: [MessageService],
})
export class ContentFormComponent implements OnInit {
  contentForm: FormGroup;
  isEditMode = false;
  contentId: string | null = null;
  loading = false;

  //TODO 未來擴充成，選項後台可以編輯，目前先寫死在前後台，因為用不到
  contentTypeOptions = contentTypeOptions;

  constructor(
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private adminContentService: AdminContentService,
    private messageService: MessageService
  ) {
    this.contentForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(3)]],
      content: ['', Validators.required],
      contentType: ['ARTICLE', Validators.required],
      isPublic: [false],
      tags: [[]],
      categoryId: [''],
    });
  }

  ngOnInit() {
    this.route.paramMap.subscribe((params) => {
      const id = params.get('id');
      if (id) {
        this.isEditMode = true;
        this.contentId = id;
        this.loadContent(this.contentId);
      }
    });
  }

  loadContent(id: string) {
    this.loading = true;

    this.adminContentService.apiAdminContentIdGet(id).subscribe({
      next: (response) => {
        const data = response.data;
        if (data) {
          this.contentForm.patchValue({
            title: data.title,
            content: data.content,
            contentType: data.contentType,

            isPublic: data.isPublic,
            tags: data.tags || [],
            categoryId: data.categoryId,
          });
        }
        this.loading = false;
      },
      error: () => {
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '無法載入內容',
        });
        this.loading = false;
        this.router.navigate(['/contents']);
      },
    });
  }

  onSubmit() {
    if (this.contentForm.valid) {
      this.loading = true;
      const formData = this.contentForm.getRawValue();

      if (this.isEditMode && this.contentId) {
        const updateData: UpdateContentRequestModel = {
          title: formData.title,
          content: formData.content,
          contentType: formData.contentType,

          isPublic: formData.isPublic,
          tags: formData.tags,
          categoryId: formData.categoryId || undefined,
        };

        this.adminContentService
          .apiAdminContentIdPut(this.contentId, updateData)
          .subscribe({
            next: () => {
              this.messageService.add({
                severity: 'success',
                summary: '成功',
                detail: '內容已更新',
              });
              this.router.navigate(['/contents']);
            },
            error: () => {
              this.messageService.add({
                severity: 'error',
                summary: '錯誤',
                detail: '無法更新內容',
              });
              this.loading = false;
            },
          });
      } else {
        const createData: CreateContentRequestModel = {
          title: formData.title,
          content: formData.content,
          contentType: formData.contentType,

          isPublic: formData.isPublic,
          tags: formData.tags,
          categoryId: formData.categoryId || undefined,
        };

        this.adminContentService.apiAdminContentPost(createData).subscribe({
          next: () => {
            this.messageService.add({
              severity: 'success',
              summary: '成功',
              detail: '內容已建立',
            });
            this.router.navigate(['/contents']);
          },
          error: () => {
            this.messageService.add({
              severity: 'error',
              summary: '錯誤',
              detail: '無法建立內容',
            });
            this.loading = false;
          },
        });
      }
    } else {
      // Mark all fields as touched to trigger validation
      Object.keys(this.contentForm.controls).forEach((key) => {
        const control = this.contentForm.get(key);
        control?.markAsTouched();
      });
    }
  }
}
