import { Pipe, type PipeTransform } from '@angular/core';
import { CONTENT_TYPE_LABELS } from '../constants/content-types.constants';

@Pipe({
  name: 'appContentType',
  standalone: true,
})
export class ContentTypePipe implements PipeTransform {
  transform(value: string): string {
    return CONTENT_TYPE_LABELS[value] || value;
  }
}
