import { Component, OnInit } from '@angular/core';
import { ConfirmationService, MessageService } from 'primeng/api';
import { ToastModule } from 'primeng/toast';
import { AdminContentService } from '../../../../../../libs/openapi/src/api/admin-content.service';
import { GetAllContentsResponseModelDataContentsInner } from '../../../../../../libs/openapi/src/model/get-all-contents-response-model-data-contents-inner';

@Component({
  selector: 'app-content-list',
  templateUrl: './content-list.component.html',
  styleUrls: ['./content-list.component.scss'],
  providers: [ConfirmationService, MessageService, ToastModule],
})
export class ContentListComponent implements OnInit {
  contents: GetAllContentsResponseModelDataContentsInner[] = [];
  loading: boolean = true;
  selectedContent: GetAllContentsResponseModelDataContentsInner | null = null;

  constructor(
    private adminContentService: AdminContentService,
    private confirmationService: ConfirmationService,
    private messageService: MessageService
  ) {}

  ngOnInit() {
    this.loadContents();
  }

  loadContents() {
    this.loading = true;

    this.adminContentService.apiAdminContentGet().subscribe({
      next: (response) => {
        this.contents = response.data?.contents || [];
        this.loading = false;
      },
      error: () => {
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '無法載入內容',
        });
        this.loading = false;
      },
    });
  }

  confirmDelete(content: GetAllContentsResponseModelDataContentsInner) {
    this.confirmationService.confirm({
      message: `確定要刪除「${content.title}」嗎？`,
      header: '確認刪除',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.deleteContent(content);
      },
    });
  }

  private deleteContent(content: GetAllContentsResponseModelDataContentsInner) {
    if (!content._id) return;

    this.adminContentService.apiAdminContentIdDelete(content._id).subscribe({
      next: () => {
        this.contents = this.contents.filter((c) => c._id !== content._id);
        this.messageService.add({
          severity: 'success',
          summary: '成功',
          detail: '內容已刪除',
        });
      },
      error: () => {
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '無法刪除內容',
        });
      },
    });
  }
}
